func mean(vals []float64) float64 {
        if len(vals) == 0 {
                return 0
        }
        sum := 0.0
        for _, v := range vals {
                sum += v
        }
        return sum / float64(len(vals))
}

func weighted(vals []float64, supports []int) float64 {
        if len(vals) == 0 {
                return 0
        }
        sumVal := 0.0
        sumSup := 0
        for i, v := range vals {
                sumVal += v * float64(supports[i])
                sumSup += supports[i]
        }
        if sumSup == 0 {
                return 0
        }
        return sumVal / float64(sumSup)
}

